// Lumenmorph and Slidebox are loaded for this playground.
const { trackPointer, enhanceSlideboxRange, enhanceSlideboxRangeFill } =
  LumenExample;
const controller = new AbortController();
const stopLight = trackPointer(document.querySelector(".lm-lab"));
const ranges = [...document.querySelectorAll("input[type=range]")].flatMap(
  (input) => [
    enhanceSlideboxRange(input, { layers: true }),
    enhanceSlideboxRangeFill(input),
  ],
);

(function (demo, signal) {
  const button = demo.querySelector("[data-ticket]");
  button.addEventListener(
    "click",
    () => {
      const details = button.getAttribute("aria-expanded") !== "true";
      button.setAttribute("aria-expanded", String(details));
      button.querySelector("span").textContent = details
        ? "Back to the ticket"
        : "See the details";
      button.querySelector("i").className =
        `fa-solid fa-${details ? "arrow-left" : "arrow-right"}`;
      demo.querySelector("[data-ticket-front]").hidden = details;
      demo.querySelector("[data-ticket-back]").hidden = !details;
    },
    { signal },
  );
})(document.querySelector(".showcase-demo"), controller.signal);

window.addEventListener("pagehide", (event) => {
  if (!event.persisted) {
    controller.abort();
    stopLight();
    ranges.forEach((stop) => stop());
  }
});
